from .model_exceptions import PackageAlreadyExists
from .package import Package


class Data(object):
    def __init__(self, domain, product):
        self.domain = domain
        self.product = product
        self.packages = {}

    def add_package(self, name, package_id):
        if package_id not in self.packages:
            self.packages[package_id] = Package(
                domain=self.domain,
                product=self.product,
                name=name,
                package_id=package_id
            )
        else:
            raise PackageAlreadyExists("Package name {} already exists in Data".format(name))
